    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    sort(a.begin(), a.end());

    long long ans = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            long long sum = a[i] + a[j];
            // count indices k > j with a[k] < sum
            int pos = lower_bound(a.begin() + j + 1, a.end(), sum) - a.begin();
            if (pos - (j + 1) > 0) ans += pos - (j + 1);
        }
    }

    cout << ans << "\n";
    return 0;
}
